def signal(obs):
    def get_mid(asset):
        m = obs.last(asset, 'mid')
        if m is None or not np.isfinite(m):
            h = obs.hist(asset, 'mid', 5)
            for v in reversed(h):
                if np.isfinite(v):
                    return float(v)
            return None
        return float(m)
    try:
        midA = get_mid('A')
        midB = get_mid('B')
        midC = get_mid('C')
        midIDX = get_mid('IDX')
        if None in (midA,midB,midC,midIDX):
            return {}
        fair = 0.3333*midA + 0.6667*midB + 0.1667*midC
        spread = midIDX - fair
        histA = obs.hist('A','mid', 80)
        histB = obs.hist('B','mid', 80)
        histC = obs.hist('C','mid', 80)
        histIDX = obs.hist('IDX','mid', 80)
        spreads = []
        for i in range(80):
            a=histA[i]; b=histB[i]; c=histC[i]; idx=histIDX[i]
            if np.isfinite(a) and np.isfinite(b) and np.isfinite(c) and np.isfinite(idx):
                f = 0.3333*a+0.6667*b+0.1667*c
                spreads.append(idx-f)
            else:
                spreads.append(np.nan)
        spreads = np.array(spreads, dtype=float)
        valid = spreads[np.isfinite(spreads)]
        if len(valid) < 20:
            std=6.0
            mean=0.0
        else:
            v = valid[-60:]
            mean = float(np.mean(v))
            std = float(np.std(v))
            if std < 2.0:
                std = 2.0
        z = (spread - mean)/std
        k=0.5
        t_idx = -z*k
        t_idx = max(-1.0, min(1.0, t_idx))
        tA = -t_idx * 0.3333
        tB = -t_idx * 0.6667
        tC = -t_idx * 0.1667
        return {'IDX': float(t_idx), 'A': float(tA), 'B': float(tB), 'C': float(tC)}
    except Exception:
        return {}

def signal(obs):
    # C momentum: past 20 return scaled
    hist = obs.hist('C','mid', 60)
    # need at least 30
    if hist[0] is None or hist[-1] is None:
        return {}
    # clean
    mids = []
    for v in hist:
        if v is not None and np.isfinite(v):
            mids.append(float(v))
        else:
            mids.append(np.nan)
    mids = np.array(mids, dtype=float)
    # if too many nans, skip
    if np.sum(np.isfinite(mids)) < 40:
        return {}
    # past returns
    # use 20 step past return normalized by vol
    # recent mid
    cur = mids[-1]
    past20 = mids[-21] if np.isfinite(mids[-21]) else np.nan
    past10 = mids[-11] if np.isfinite(mids[-11]) else np.nan
    if not np.isfinite(past20) or not np.isfinite(cur):
        return {}
    ret20 = cur - past20
    ret10 = cur - past10 if np.isfinite(past10) else 0.0
    # combine
    # estimate vol last 30
    rets = np.diff(mids)
    rets = rets[np.isfinite(rets)]
    if len(rets) < 20:
        return {}
    vol = np.std(rets[-30:]) if len(rets)>=30 else np.std(rets)
    if vol < 0.5:
        vol = 0.5
    # z score
    z = ret20 / (vol * np.sqrt(20))
    # threshold
    # map z to target: sigmoid
    # require |z|>0.8 to trade
    if abs(z) < 0.8:
        return {'C': 0.0}
    # position proportional to sign and magnitude capped
    target = np.tanh(z * 0.8)  # tame
    # clip
    if target > 1: target=1
    if target < -1: target=-1
    return {'C': float(target)}

def signal(obs):
    # Attempt to fix IDX arb sign - maybe we inverted? Spread positive means IDX rich => should short IDX long basket -> t_idx negative, tA positive. That we did.
    # But backtest lost money, suggests spread momentum not mean reversion at short horizon? But analyze showed -0.3 to -0.55 correlation mean reversion.
    # Maybe we used zero fee but still lost due to crossing spread and trend? Let's amplify threshold and look longer horizon 50.
    # Use 50-step mean revert slope ~ -0.7, that suggests strong reversion but slow.
    # Perhaps our rolling mean/std lookback 60 is too short; spread is persistent (ac ~0.9)
    # Try zscore vs longer lookback 200 and trade only extremes |z|>1.5 and smaller size.
    def get_mid(asset):
        m = obs.last(asset, 'mid')
        if m is None or not np.isfinite(m):
            h = obs.hist(asset, 'mid', 5)
            for v in reversed(h):
                if np.isfinite(v):
                    return float(v)
            return None
        return float(m)
    try:
        midA = get_mid('A'); midB = get_mid('B'); midC = get_mid('C'); midIDX = get_mid('IDX')
        if None in (midA,midB,midC,midIDX):
            return {}
        fair = 0.3333*midA + 0.6667*midB + 0.1667*midC
        spread = midIDX - fair
        histA = obs.hist('A','mid', 250)
        histB = obs.hist('B','mid', 250)
        histC = obs.hist('C','mid', 250)
        histIDX = obs.hist('IDX','mid', 250)
        spreads=[]
        for i in range(250):
            a=histA[i]; b=histB[i]; c=histC[i]; idx=histIDX[i]
            if np.isfinite(a) and np.isfinite(b) and np.isfinite(c) and np.isfinite(idx):
                spreads.append(idx - (0.3333*a+0.6667*b+0.1667*c))
            else:
                spreads.append(np.nan)
        spreads=np.array(spreads,float)
        valid=spreads[np.isfinite(spreads)]
        if len(valid)<100:
            return {}
        mean=float(np.mean(valid[-200:])) if len(valid)>=200 else float(np.mean(valid))
        std=float(np.std(valid[-200:])) if len(valid)>=200 else float(np.std(valid))
        if std<3: std=3
        z=(spread-mean)/std
        if abs(z)<1.2:
            return {'IDX':0.0,'A':0.0,'B':0.0,'C':0.0}
        k=0.4
        t_idx=-z*k
        t_idx=max(-1.0,min(1.0,t_idx))
        # also reduce hedge size to avoid C momentum conflict: maybe hedge less C because C trends? But basket requires C.
        tA=-t_idx*0.3333
        tB=-t_idx*0.6667
        tC=-t_idx*0.1667
        return {'IDX':float(t_idx),'A':float(tA),'B':float(tB),'C':float(tC)}
    except Exception:
        return {}

def signal(obs):
    # C momentum using average of C and C.X to reduce noise, vol-normalized past return
    hist = obs.hist('C', 'mid', 80)
    histX = obs.hist('C.X', 'mid', 80)
    avg = []
    for a, b in zip(hist, histX):
        fa = float(a) if a is not None and np.isfinite(a) else np.nan
        fb = float(b) if b is not None and np.isfinite(b) else np.nan
        if np.isfinite(fa) and np.isfinite(fb):
            avg.append((fa + fb) * 0.5)
        elif np.isfinite(fa):
            avg.append(fa)
        elif np.isfinite(fb):
            avg.append(fb)
        else:
            avg.append(np.nan)
    avg = np.array(avg, dtype=float)
    # need enough history
    cnt = 0
    for v in avg:
        if np.isfinite(v):
            cnt += 1
    if cnt < 60:
        return {}
    cur = avg[-1]
    past30 = avg[-31]
    past10 = avg[-11]
    if not np.isfinite(cur) or not np.isfinite(past30):
        return {}
    ret30 = cur - past30
    ret10 = cur - past10 if np.isfinite(past10) else 0.0
    # rolling vol of avg changes
    # compute diff where both finite
    rets = []
    for i in range(1, len(avg)):
        if np.isfinite(avg[i]) and np.isfinite(avg[i-1]):
            rets.append(float(avg[i] - avg[i-1]))
    if len(rets) < 20:
        return {}
    rets_arr = np.array(rets, dtype=float)
    # take last 40
    if len(rets_arr) >= 40:
        vol = float(np.std(rets_arr[-40:]))
    else:
        vol = float(np.std(rets_arr))
    if not np.isfinite(vol) or vol < 0.6:
        vol = 0.6
    sig_raw = 0.7 * ret30 + 0.3 * ret10
    z = sig_raw / (vol * 5.477225575051661)  # sqrt(30)
    if not np.isfinite(z):
        return {}
    # dead zone small signal -> flat to avoid noise and fees
    if abs(z) < 0.4:
        return {'C': 0.0, 'C.X': 0.0}
    # scale with tanh, tame factor 0.6
    target = float(np.tanh(z * 0.6))
    if abs(z) < 0.6:
        target = target * 0.5
    if target > 1.0:
        target = 1.0
    if target < -1.0:
        target = -1.0
    # fee-aware allocation: C venue 0bps cheaper than C.X 3bps
    return {'C': float(target * 0.9), 'C.X': float(target * 0.5)}

