def corr(x,y):
    m=np.nanmean(x); n=np.nanmean(y)
    xm=x-m; ym=y-n
    denom=np.sqrt(np.nansum(xm**2)*np.nansum(ym**2))
    if denom==0:
        return 0
    return np.nansum(xm*ym)/denom
def autocorr(x,lag):
    x1=x[lag:]; x0=x[:-lag]
    mask=np.isfinite(x1)&np.isfinite(x0)
    if np.sum(mask)<10:
        return float('nan')
    return corr(x1[mask],x0[mask])

