def half_life(mis_chunk):
    m=mis_chunk[np.isfinite(mis_chunk)]
    if len(m)<20:
        return float('nan')
    x=m[:-1]; y=np.diff(m)
    mask=np.isfinite(x)&np.isfinite(y)
    x=x[mask]; y=y[mask]
    # beta = cov(y,x)/var(x)
