def signal(obs):
    # index arb: IDX vs basket (A,B,C primaries)
    st = obs.state
    try:
        n = 400
        a = obs.hist('A', 'mid', n)
        b = obs.hist('B', 'mid', n)
        c = obs.hist('C', 'mid', n)
        idx = obs.hist('IDX', 'mid', n)
        # need enough finite
        basket = 0.3333*a + 0.6667*b + 0.1667*c
        diff = idx - basket
        m = np.isfinite(diff)
        if np.sum(m) < 200:
            return {}
        d = diff[m]
        mu = float(np.mean(d[-300:])) if len(d)>=300 else float(np.mean(d))
        sd = float(np.std(d[-300:])) if len(d)>=300 else float(np.std(d))
        if not np.isfinite(mu) or not np.isfinite(sd) or sd < 5:
            return {}
        cur = float(diff[-1])
        if not np.isfinite(cur):
            return {}
        z = (cur - mu)/sd
        # deadband
        # scale: full position at |z|=2.5
        s = (abs(z)-0.75)/ (2.5-0.75)
        if s < 0:
            s = 0.0
        if s > 1:
            s = 1.0
        direction = -1.0 if z > 0 else 1.0  # short IDX if rich
        # smooth: store prev
        prev = st.get('pos', 0.0)
        tgt = direction * s
        # exponential smoothing to reduce turnover
        sm = 0.5*prev + 0.5*tgt
        st['pos'] = sm
        # map to targets with hedge ratios
        return {'IDX': float(sm), 'A': float(-sm*0.3333), 'B': float(-sm*0.6667), 'C': float(-sm*0.1667)}
    except Exception:
        return {}

