    out = {}
    for a in ['A','C','IDX']:
        try:
            m = obs.hist(a, 'mid', 80)
        except Exception:
            continue
        if m is None or len(m) < 60:
            continue
        cur = m[-1]
        past = m[-51] if len(m) >= 51 else m[0]
        if cur != cur or past != past:
            continue
        ret = (cur - past) / 50.0
        # scale: vol per step approx A 1.4, C 3.6, IDX 1.3
