        t = ret / (scale*2.0)
        if t > 1: t = 1
        if t < -1: t = -1
        # deadzone to reduce turnover
        if abs(t) < 0.15:
            t = 0.0
        out[a] = float(t)
    # B mean reversion: fade past 10-step move
    try:
        m = obs.hist('B','mid',30)
        if m is not None and len(m)>=11:
            cur=m[-1]; past=m[-11]
            if cur==cur and past==past:
                ret=(cur-past)/10.0
                t=-ret/(3.5*2.0)
                if t>1: t=1
                if t<-1: t=-1
                if abs(t)<0.15: t=0.0
                out['B']=float(t)
    except Exception:
        pass
    return out

