    try:
        a = obs.last('A','mid'); b = obs.last('B','mid'); c = obs.last('C','mid'); idx = obs.last('IDX','mid')
        syn = 0.3333*a + 0.6667*b + 0.1667*c
        spread = idx - syn
        # scale: std ~23, threshold trade when |spread|>T
        T = 30.0
        # z-score clip
        import math as m
        s = max(-1.0, min(1.0, spread/60.0))
        # deadzone
        if abs(spread) < T:
            return {}
        # short spread: short IDX, long basket
        # targets: IDX = -sign*mag, components = +sign*mag*w
        sign = 1.0 if spread>0 else -1.0
        mag = min(1.0, (abs(spread)-T)/60.0 + 0.3)
        return {'IDX': -sign*mag, 'A': sign*mag*0.3333, 'B': sign*mag*0.6667, 'C': sign*mag*0.1667}
    except Exception:
        return {}

